<?php $category=mysqli_fetch_assoc($category);if(!$category){http_response_code(404);echo '<section class="sc-store"><h1>Category not found</h1></section>';return;}$products=sc_query('SELECT p.*, c.slug AS category_slug FROM products p JOIN product_categories c ON c.id=p.category_id WHERE p.category_id=? AND p.is_active=1 AND p.is_deleted=0 ORDER BY p.product_name','i',[$category['id']])->get_result(); ?>
<section class="sc-store"><span class="sc-kicker">THE STEPCURE COLLECTION</span><h1><?= sc_e($category['category_name']) ?></h1><p>Explore available footwear and support. Prices shown in Indian rupees, before applicable tax.</p><?php if($GLOBALS['sc_error']): ?><div class="alert alert-danger"><?= sc_e($GLOBALS['sc_error']) ?></div><?php endif; ?><div class="sc-shop-grid"><?php while($p=$products->fetch_assoc()): $available=sc_available($p['id']); ?><article class="sc-shop-card"><a href="<?= sc_url('products/'.rawurlencode($p['category_slug']).'/'.rawurlencode($p['slug'])) ?>"><img src="<?= sc_e(sc_image($p)) ?>" alt="<?= sc_e($p['product_name']) ?>" loading="lazy"><h2><?= sc_e($p['product_name']) ?></h2></a><p><?= sc_money(sc_price($p)) ?> <small>+ applicable tax</small></p><p class="sc-stock-status <?= $available?'':'is-empty' ?>"><?= $available?'In stock: ' . $available:'Out of stock' ?></p><?php if(sc_price($p)>0 && $available>0): ?><form method="post" action="<?= sc_url('cart') ?>"><?= sc_token() ?><input type="hidden" name="sc_action" value="cart_add"><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><button class="sc-buy" type="submit">Add to cart +</button></form><?php else: ?><a href="<?= sc_url('contact') ?>">Contact for availability</a><?php endif; ?></article><?php endwhile; ?></div><?php if(!$products->num_rows): ?><div class="sc-panel"><p>No products are available in this category yet.</p><a href="<?= sc_url('products') ?>">Browse other categories</a></div><?php endif; ?></section>
